window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5e991a4d43a7f353"]={"versions": [{"id": "FIG-5e991a4d43a7f353", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (Execution Management). Das Diagramm stellt die Schnittstelle <code>ExecutionClient</code> dar, über die daemon-basierte funktionale Cluster der Plattform ihren Ausführungsstatus an das <code>Execution Management</code> melden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Execution Management</strong>: Funktionaler Cluster (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>), realisiert die Schnittstelle <code>ExecutionClient</code> via Interface-Realisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).\n</li><li><strong>ExecutionClient</strong>: C++-API bzw. natives Interface (<code>«aapAPI,aapNativeInterface»</code>) mit der Operation:\n<ul class=\"fig-list\"><li><code>+ ReportExecutionState(ExecutionState): Result</code>\n</li></ul>\n</li><li><strong>Nutzende funktionale Cluster</strong> (alle als <code>«aapFunctionalCluster»</code>, <code>daemon-based</code> typisiert):\n<ul class=\"fig-list\"><li><code>State Management</code>\n</li><li><code>Platform Health Management</code>\n</li><li><code>Diagnostic Management</code>\n</li><li><code>Update and Configuration Management</code>\n</li><li><code>Time Synchronization</code>\n Jeder dieser Cluster besitzt eine gerichtete Abhängigkeitsbeziehung (<code>«use»</code>, gestrichelter Pfeil mit offener Spitze) auf <code>ExecutionClient</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Verwendungsbeziehung. Jeder daemon-basierte funktionale Cluster nutzt zur Laufzeit die Schnittstelle <code>ExecutionClient</code>, um dem <code>Execution Management</code> Zustandsübergänge des eigenen Prozesses über den Methodenaufruf <code>ReportExecutionState(ExecutionState)</code> mitzuteilen und ein entsprechendes Ausführungsergebnis (<code>Result</code>) zu empfangen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren von AUTOSAR Adaptive Plattformdiensten normativ bindend: Daemon-basierte funktionale Cluster dürfen nicht isoliert laufen, sondern müssen ihren Zustand aktiv an das <code>Execution Management</code> melden. Die Interaktion erfolgt synchron über die native Programmierschnittstelle <code>ExecutionClient</code>.</p>"}, {"id": "FIG-d0eda9790641810a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (Execution Management). Das Diagramm stellt die Schnittstelle <code>ExecutionClient</code> dar, über die daemon-basierte funktionale Cluster der Plattform ihren Ausführungsstatus an das <code>Execution Management</code> melden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Execution Management</strong>: Funktionaler Cluster (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>), realisiert die Schnittstelle <code>ExecutionClient</code> via Interface-Realisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).\n</li><li><strong>ExecutionClient</strong>: C++-API bzw. natives Interface (<code>«aapAPI,aapNativeInterface»</code>) mit der Operation:\n<ul class=\"fig-list\"><li><code>+ ReportExecutionState(ExecutionState): Result</code>\n</li></ul>\n</li><li><strong>Nutzende funktionale Cluster</strong> (alle als <code>«aapFunctionalCluster»</code>, <code>daemon-based</code> typisiert):\n<ul class=\"fig-list\"><li><code>State Management</code>\n</li><li><code>Platform Health Management</code>\n</li><li><code>Diagnostic Management</code>\n</li><li><code>Update and Configuration Management</code>\n</li><li><code>Time Synchronization</code>\n Jeder dieser Cluster besitzt eine gerichtete Abhängigkeitsbeziehung (<code>«use»</code>, gestrichelter Pfeil mit offener Spitze) auf <code>ExecutionClient</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Verwendungsbeziehung. Jeder daemon-basierte funktionale Cluster nutzt zur Laufzeit die Schnittstelle <code>ExecutionClient</code>, um dem <code>Execution Management</code> Zustandsübergänge des eigenen Prozesses über den Methodenaufruf <code>ReportExecutionState(ExecutionState)</code> mitzuteilen und ein entsprechendes Ausführungsergebnis (<code>Result</code>) zu empfangen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren von AUTOSAR Adaptive Plattformdiensten normativ bindend: Daemon-basierte funktionale Cluster dürfen nicht isoliert laufen, sondern müssen ihren Zustand aktiv an das <code>Execution Management</code> melden. Die Interaktion erfolgt synchron über die native Programmierschnittstelle <code>ExecutionClient</code>.</p>"}, {"id": "FIG-e461fdfae372d5b4", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (Execution Management). Das Diagramm stellt die Schnittstelle <code>ExecutionClient</code> dar, über die daemon-basierte funktionale Cluster der Plattform ihren Ausführungsstatus an das <code>Execution Management</code> melden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Execution Management</strong>: Funktionaler Cluster (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>), realisiert die Schnittstelle <code>ExecutionClient</code> via Interface-Realisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).\n</li><li><strong>ExecutionClient</strong>: C++-API bzw. natives Interface (<code>«aapAPI,aapNativeInterface»</code>) mit den Operationen:\n<ul class=\"fig-list\"><li><code>+ Create()</code> (statische Erzeugungsmethode / Factory, unterstrichen)\n</li><li><code>+ ReportExecutionState(ExecutionState): Result</code>\n</li></ul>\n</li><li><strong>Nutzende funktionale Cluster</strong> (alle als <code>«aapFunctionalCluster»</code>, <code>daemon-based</code> typisiert):\n<ul class=\"fig-list\"><li><code>State Management</code>\n</li><li><code>Platform Health Management</code>\n</li><li><code>Diagnostic Management</code>\n</li><li><code>Update and Configuration Management</code>\n</li><li><code>Time Synchronization</code>\n Jeder dieser Cluster besitzt eine gerichtete Abhängigkeitsbeziehung (<code>«use»</code>, gestrichelter Pfeil mit offener Spitze) auf <code>ExecutionClient</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Verwendungsbeziehung. Daemon-basierte funktionale Cluster instanziieren den Client über die Factory-Methode <code>Create()</code> und melden ihren Prozesszustand an das <code>Execution Management</code> mittels <code>ReportExecutionState(ExecutionState)</code> unter Rückgabe eines <code>Result</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Implementierung von Plattform-Daemon-Clustern normativ: Der Lebenszyklus der Client-Instanz wird über die statische Factory-Methode <code>Create()</code> initiiert. Die Zustandsmeldung an das <code>Execution Management</code> erfolgt über <code>ReportExecutionState(...)</code>.</p>"}, {"id": "FIG-d016c95609982ba0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (Execution Management). Das Diagramm stellt die Schnittstelle <code>ExecutionClient</code> dar, über die daemon-basierte funktionale Cluster der Plattform ihren Ausführungsstatus an das <code>Execution Management</code> melden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Execution Management</strong>: Funktionaler Cluster (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>), realisiert die Schnittstelle <code>ExecutionClient</code> via Interface-Realisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).\n</li><li><strong>ExecutionClient</strong>: C++-API bzw. natives Interface (<code>«aapAPI,aapNativeInterface»</code>) mit den Operationen:\n<ul class=\"fig-list\"><li><code>+ Create()</code> (statische Erzeugungsmethode / Factory, unterstrichen)\n</li><li><code>+ ReportExecutionState(ExecutionState): Result</code>\n</li></ul>\n</li><li><strong>Nutzende funktionale Cluster</strong> (alle als <code>«aapFunctionalCluster»</code>, <code>daemon-based</code> typisiert):\n<ul class=\"fig-list\"><li><code>State Management</code>\n</li><li><code>Platform Health Management</code>\n</li><li><code>Diagnostic Management</code>\n</li><li><code>Update and Configuration Management</code>\n</li><li><code>Time Synchronization</code>\n Jeder dieser Cluster besitzt eine gerichtete Abhängigkeitsbeziehung (<code>«use»</code>, gestrichelter Pfeil mit offener Spitze) auf <code>ExecutionClient</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Verwendungsbeziehung. Daemon-basierte funktionale Cluster instanziieren den Client über die Factory-Methode <code>Create()</code> und melden ihren Prozesszustand an das <code>Execution Management</code> mittels <code>ReportExecutionState(ExecutionState)</code> unter Rückgabe eines <code>Result</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Implementierung von Plattform-Daemon-Clustern normativ: Der Lebenszyklus der Client-Instanz wird über die statische Factory-Methode <code>Create()</code> initiiert. Die Zustandsmeldung an das <code>Execution Management</code> erfolgt über <code>ReportExecutionState(...)</code>.</p>"}, {"id": "FIG-64abadcb90086349", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (Execution Management). Das Diagramm stellt die Schnittstelle <code>ExecutionClient</code> dar, über die sämtliche daemon-basierten funktionalen Cluster der Plattform ihren Ausführungsstatus an das zentral zuständige <code>Execution Management</code> melden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Execution Management</strong>: Funktionaler Cluster (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>), realisiert die Schnittstelle <code>ExecutionClient</code> via Interface-Realisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).\n</li><li><strong>ExecutionClient</strong>: C++-API bzw. natives Interface (<code>«aapAPI,aapNativeInterface»</code>) mit den Operationen:\n<ul class=\"fig-list\"><li><code>+ Create()</code> (statische Methode, unterstrichen)\n</li><li><code>+ ReportExecutionState(ExecutionState)</code>\n</li></ul>\n</li><li><strong>Nutzende funktionale Cluster</strong> (alle als <code>«aapFunctionalCluster»</code> bzw. <code>«aapFunctionalCl...»</code>, <code>daemon-based</code> typisiert, jeweils mit einer gerichteten <code>«use»</code>-Abhängigkeit auf <code>ExecutionClient</code>):\n<ul class=\"fig-list\"><li><code>Time Synchronization</code>\n</li><li><code>Automotive API Gateway</code>\n</li><li><code>Communication Management</code>\n</li><li><code>Network Management</code>\n</li><li><code>State Management</code>\n</li><li><code>Platform Health Management</code>\n</li><li><code>Diagnostic Management</code>\n</li><li><code>Update and Configuration Management</code>\n</li><li><code>Vehicle Update and Configuration Management</code>\n</li><li><code>Intrusion Detection System Manager</code>\n</li><li><code>Cryptography</code>\n</li><li><code>Firewall</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Abhängigkeitsstruktur. Alle daemon-basierten funktionalen Cluster der Plattform erzeugen eine Instanz über <code>Create()</code> und übermitteln ihren jeweiligen Prozess- und Ausführungszustand mittels <code>ReportExecutionState(ExecutionState)</code> an das <code>Execution Management</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische und funktionale Pflicht für Plattformdienste: Sämtliche aufgeführten zwölf daemon-basierten funktionalen Cluster müssen zur Synchronisation des Plattformlebenszyklus die Schnittstelle <code>ExecutionClient</code> einbinden und ihren Zustand per <code>ReportExecutionState(ExecutionState)</code> melden.</p>"}], "trans": [{"from": "FIG-5e991a4d43a7f353", "to": "FIG-d0eda9790641810a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d0eda9790641810a", "to": "FIG-e461fdfae372d5b4", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>ExecutionClient</strong>: Statische Factory-Methode <code>+ Create()</code> als Operation ergänzt.\n</li></ul>"}, {"from": "FIG-e461fdfae372d5b4", "to": "FIG-d016c95609982ba0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d016c95609982ba0", "to": "FIG-64abadcb90086349", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>ExecutionClient</strong>: Rückgabetyp <code>: Result</code> bei der Operation <code>ReportExecutionState(ExecutionState)</code> entfernt.\n</li><li><strong>Funktionale Cluster</strong>: Sieben daemon-basierte funktionale Cluster als Nutzer (<code>«use»</code>) des <code>ExecutionClient</code> ergänzt: <code>Automotive API Gateway</code>, <code>Communication Management</code>, <code>Network Management</code>, <code>Vehicle Update and Configuration Management</code>, <code>Intrusion Detection System Manager</code>, <code>Cryptography</code>, <code>Firewall</code>.\n</li><li><strong>Layout</strong>: Umstrukturierung der nutzenden Komponenten in zwei Zeilen oberhalb sowie eine Zeile unterhalb der Schnittstelle <code>ExecutionClient</code>.\n</li></ul>"}]};
